text=text.replace("assert(!await ui.locator('#browser-setup').isVisible());check('After dedicated native registration the real polling handshake connects the existing software and dismisses the install guide');", "assert(await ui.locator('#browser-pair').isDisabled());assert.equal(await ui.locator('#connection-light').getAttribute('data-connected'),'true');check('After dedicated registration the real polling handshake makes EXE and web green and confirms pairing');await panel.screenshot({path:path.join(root,'outputs/EXE配对成功-0.17.3.png')});")
